
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_xc_tpss0_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_xc_tpss0", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.591132490386282e+00, -3.519055576887494e+00, -3.418008895087061e+00, -3.277934557450040e+00, -3.086871328475929e+00, -2.832229989237477e+00, -2.503983979545777e+00, -2.101024392546019e+00, -1.642590979117153e+00, -1.184007922615911e+00, -7.864005754263956e-01, -5.579783559073100e-01, -4.970496121042848e-01, -4.160356421600500e-01, -2.927838910523221e-01, -1.782422921663356e-01, -9.875660887649082e-02, -3.712879315060222e-02, -8.108938866651831e-03, -9.121516112387035e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


